jq -n --slurpfile enc "$work/enc.json" --slurpfile base "$node_dir/config.json" --slurpfile result "$result" --arg uuid "$uuid" --argjson port "$port" --arg domain "$http_host" --arg path "$path" --arg cert "$certificate" --arg key "$key" --argjson alpn '["h3"]' --argjson xhttp '{"mode":"packet-up","extra":{"uplinkHTTPMethod":"GET","uplinkDataPlacement":"header","uplinkDataKey":"data","scMaxEachPostBytes":4096}}' '
  {log:{loglevel:"warning"},inbounds:[{listen:"::",port:$port,protocol:"vless",settings:{clients:[{id:$uuid,flow:"xtls-rprx-vision"}],decryption:$enc[0].decryption},streamSettings:{network:"xhttp",security:"tls",tlsSettings:{alpn:$alpn,certificates:[{certificateFile:$cert,keyFile:$key}]} ,xhttpSettings:($xhttp+{host:$domain,path:$path})}}],outbounds:[{protocol:"freedom"}]}' > "$node_dir/config.xhttp.new"
"$xray" run -test -format json -config stdin: < "$node_dir/config.xhttp.new" >/dev/null 2>&1
# Keep the original config/unit until Xray has actually started.
cp -p "$node_dir/config.json" "$work/config.before"
cp -p "$result" "$work/result.before"
case "$mode" in
  systemd) unit="/etc/systemd/system/$service.service";;
  openrc) unit="/etc/init.d/$service";;
  *) exit 1;;
esac
cp -p "$unit" "$work/unit.before"
restore_base() {
  cp -p "$work/config.before" "$node_dir/config.json"
  cp -p "$work/result.before" "$result"
  cp -p "$work/unit.before" "$unit"
  if [ "$mode" = systemd ]; then systemctl daemon-reload; systemctl restart "$service"; else rc-service "$service" restart >/dev/null; fi
}
trap 'restore_base; echo INSTALL_FAILED:XHTTP_SETUP_FAILED; exit 1' ERR
mv "$node_dir/config.xhttp.new" "$node_dir/config.json"
if [ "$mode" = systemd ]; then
  cat > "$unit" <<EOF
[Unit]
Description=SimpleNet Xray XHTTP ${name}
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$xray run -config $node_dir/config.json
Restart=on-failure
RestartSec=3
[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload; systemctl enable "$service" >/dev/null 2>&1; systemctl restart "$service"; systemctl is-active --quiet "$service"
else
  cat > "$unit" <<EOF
#!/sbin/openrc-run
command="$xray"
command_args="run -config $node_dir/config.json"
command_background=true
pidfile="/run/$service.pid"
depend() { need net; }
EOF
  chmod 755 "$unit"
  rc-update add "$service" default >/dev/null 2>&1 || :; rc-service "$service" restart >/dev/null; rc-service "$service" status >/dev/null
fi
jq --slurpfile enc "$work/enc.json" --arg domain "$domain" --arg http_host "$http_host" --argjson origin_h2 false --argjson origin_cdn false --arg tls_mode 'explicit' --arg path "$path" --arg core "$xray" --arg protocol 'vless-xhttp-h3' --argjson port "$port" '
  . + {protocol:$protocol,port:$port,listen_port:$port,server:$domain,domain:$domain,origin_sni:$domain,origin_http_host:$http_host,origin_h2:$origin_h2,origin_cdn:$origin_cdn,tls_mode:$tls_mode,xhttp_path:$path,xhttp_mode:"packet-up",encryption:$enc[0].encryption,flow:"xtls-rprx-vision",core_path:$core,local_test:"passed"}
  | del(.private_key,.share_link,.public_key,.short_id,.sni)' "$result" > "$result.new"
mv "$result.new" "$result"
rm -f "$work/enc-output" "$work/enc.json"
chmod 600 "$node_dir/config.json" "$result"
trap - ERR


result="/etc/sing-box/nodes/${name}/result.json"
# Only the final protocol's parameters are exported; base Reality parameters may have been replaced.
jq --arg protocol 'vless-xhttp-h3' --arg label "${name}" '
  . + {protocol:$protocol}
  | .share_link = (
    (.server // .host | if contains(":") then "[" + . + "]" else . end) as $server
    | (.port|tostring) as $port | ($label|@uri) as $name
    | "vless://" + .uuid + "@" + $server + ":" + $port + "?encryption=" + ((.encryption // "none")|@uri) + "&flow=" + ((.flow // "")|@uri) + "&security=" + (if $protocol == "vless-xhttp-reality" then "reality" else "tls" end) + "&sni=" + ((.sni // .domain)|@uri) + "&type=xhttp&host=" + ((.origin_http_host // .sni // .domain)|@uri) + "&path=" + (.xhttp_path|@uri) + "&mode=" + (.xhttp_mode|@uri) + (if $protocol == "vless-xhttp-reality" then "&fp=firefox&pbk=" + (.public_key|@uri) + "&sid=" + (.short_id|@uri) elif $protocol == "vless-xhttp-tls" then "" else "&alpn=" + (if $protocol == "vless-xhttp-h3" then "h3" else "h2" end) + "&extra=" + ({"uplinkHTTPMethod":"GET","uplinkDataPlacement":"header","uplinkDataKey":"data","scMaxEachPostBytes":4096} | tojson | @uri) end) + "#" + $name)
' "$result" > "$result.new"
mv "$result.new" "$result"
jq -er '.share_link' "$result" > "/etc/sing-box/nodes/${name}/share-link.txt"
printf '\n节点已安装，分享链接：\n'
jq -er '.share_link' "$result"
printf '服务启动不等于公网可达，请核对目标服务器端口、防火墙和 CDN 配置。\n'

  );;
esac
